##################################
#        API for eLSU O&M        #
##################################
MAX_LOGFILE_SIZE = 1024 * 1024 *1024 # pymosaic log filesize (1GB)


def pe_log(log_output, log_buffer, output, dbglev=0, robot_output=True):
    """
        print string in output log.

        :parameter log_output: remove tar '*INFO*' from output
        :parameter log_buffer: store output
        :parameter output: log string
        :parameter dbglev: print debug level, 0=default, 1=print stak

        :return: None
    """
    try:
        tmp = pe_log.logfilesize
    except AttributeError:
        pe_log.logfilesize = 0

    try:
        tmp = pe_log.vol
    except AttributeError:
        pe_log.vol = 0
    global tmplogfile
    ltime = datetime.now().strftime('%Y%m%d-%H%M%S')
    if dbglev:
        lstk = [x[2] for x in traceback.extract_stack()]
        if len(lstk) > 3:
            lstk = lstk[3:-1]
        #ltime = ltime + ' ' + str(lstk)
        ltime = ltime + ' ' + "[" + "->".join(lstk) + "]\t"
    if platform.python_implementation() == 'IronPython' or robot_output == False:
        if '*DEBUG*' not in output:
            output = str(output).replace('*INFO* ', '')
            output = str(output).replace('*WARN* ', '')
            print(output)
        output.replace('*DEBUG*', '')
        tmplogfile.write(ltime + ' ' + str(output))
        tmplogfile.write("\n")
        tmplogfile.flush()
    else:
        if robot_output == False:
            print (str(output).replace("*DEBUG*", ""))
        elif "*DEBUG*" in str(output):
            logger.debug(str(output).replace("*DEBUG*", ""))
        elif "*INFO*" in str(output):
            logger.info(str(output).replace("*INFO*", ""))
        elif "*WARN*" in str(output):
            logger.warn(str(output).replace("*WARN*", ""))
        else:
            logger.info(str(output))
        if log_output is True:
            if '*DEBUG*' not in output:
                str(output).replace('*INFO*', '')
                log_buffer.append(output)
    try:
        logger.log_background_messages()
    except:
        pass
    # manage file size, if too big create new one.
    pe_log.logfilesize += len(output)
    if pe_log.logfilesize > MAX_LOGFILE_SIZE:
        print("INFO* pe_log(): logsize = {0}".format(pe_log.logfilesize))
        if platform.python_implementation() == 'IronPython':
            filename = tempfile.gettempdir() + '/' + ltime + "-" + 'PATE_DEBUG.txt'
            tmplogfile.close()
            tmplogfile = open(filename, 'w')
            print("*INFO* [pymosaic lib] saving log on new file " + str(filename))
        else:
            logname = sys.stdout.name
            oldname = logname + ".part.{0}_{1}".format(pe_log.vol, ltime)
            print("*INFO* saving log file as " + oldname)
            sys.stdout.close()
            os.rename(logname, oldname)
            sys.stdout = open(logname, "w+", buffering=1)
            print("*DEBUG* previous log file saved as " + oldname)
            pe_log.vol += 1
        pe_log.logfilesize = 0
